import java.util.Scanner;

public class Main {
    static int Mod;
    static int n, k;
    static long[] factorials;
    static long[] invFactorials;
    static long[] inverses;
    static long[][] memo;

    static long binPow(long base, int exp) {
        long result = 1;
        long cur = base;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                result = (result * cur) % Mod;
            }
            cur = (cur * cur) % Mod;
            exp >>= 1;
        }
        return result;
    }

    static long dfs(int used, int subset) {
        if (memo[used][subset] != -1) {
            return memo[used][subset];
        }
        long answer = 0;
        if (subset == 0) {
            answer = factorials[n];
            for (int i = 1; i <= used; ++i) {
                answer = (answer * (k - i + 1)) % Mod;
            }
            return memo[used][subset] = answer;
        }
        if (used > k) {
            return 0;
        }
        int lowest_bit = subset & (-subset);
        int remaining = subset - lowest_bit;
        for (int T = remaining; ; T = (T - 1) & remaining) {
            answer = (answer + invFactorials[subset - T] * dfs(used + 1, T) % Mod) % Mod;
            if (T == 0) break;
        }
        return memo[used][subset] = answer;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        k = sc.nextInt();
        Mod = sc.nextInt();

        if (n % 2 == 1) {
            System.out.println(binPow(k, n));
            sc.close();
            return;
        }

        factorials = new long[n + 1];
        invFactorials = new long[n + 1];
        inverses = new long[n + 1];
        memo = new long[19][n + 1];

        factorials[0] = 1;
        invFactorials[0] = 1;
        factorials[1] = 1;
        invFactorials[1] = 1;

        for (int i = 2; i <= n; ++i) {
            factorials[i] = (factorials[i - 1] * i) % Mod;
            inverses[i] = ((Mod - Mod / i) * invFactorials[Mod % i]) % Mod;
            invFactorials[i] = (invFactorials[i - 1] * inverses[i]) % Mod;
        }

        for (int i = 0; i <= 18; ++i) {
            for (int j = 0; j <= n; ++j) {
                memo[i][j] = -1;
            }
        }

        long result = (binPow(k, n) - dfs(0, n) + Mod) % Mod;
        System.out.println(result);
        sc.close();
    }
}
